edits.newString:
onComplete: (text: string, model: string, source: string) => {
  if (resolved) return;
  resolved = true;
  setIsStreaming(false);
  setStreamingText('');
  setHasFirstToken(false);
  abortControllerRef.current = null;

  const finalResponse: PublicChatApiResponse = {
    ok: true,
    requestId,
    sessionId: finalSessionId,
    answer: text || finalText,
    model,
    source: source as 'chatgpt' | 'fallback',
    deploymentMarker: 'ivx-public-chat-stream',
    rateLimitRemaining: 19,
    rateLimitResetAt: new Date(Date.now() + 300000).toISOString(),
    timestamp: new Date().toISOString(),
    endpoint: null,
    persistence: 'supabase',
  };
  resolve(finalResponse);

  // If an autonomous job was created, start polling for real status
  const capturedJobId = activeJobIdRef.current;
  if (capturedJobId && source === 'autonomous') {
    void pollSeniorDeveloperWorkerJob(capturedJobId, {
      intervalMs: 5000,
      timeoutMs: 300000,
      onTick: (job: WorkerJobView) => {
        setJobProgress({
          status: job.status,
          stage: job.result?.finalStatus ?? 'running',
          percent: job.status === 'completed' ? 100 : job.status === 'running' ? 50 : 0,
        });
      },
    }).then((finalJob) => {
      if (finalJob) {
        setJobProgress({
          status: finalJob.status,
          stage: finalJob.result?.finalStatus ?? 'unknown',
          percent: finalJob.status === 'completed' ? 100 : 0,
        });
      }
    }).catch(() => {
      // Polling errors are non-fatal — job continues server-side
    });
  }
},

